dict(param='PRIV',score=2,stance='contests',key='garfinkleMerchantsStateFormation2010',where='Garfinkle 2010, p. 186',
  quote="Our assumptions about the development of the state in antiquity ordinarily call for the presence of a coercive authority that was able to ruthlessly exploit the economy for the benefit of the royal authority ... This evidence suggests that the merchants helped to pave the way for the growth of the state while operating outside of its direct control."),
