dict(param='TEMP', score=2, stance='supports', key='charpinHistoryAncientMesopotamia1995', where='p. 812', quote="He reorganized temple management, set up a permanent military force, and created at Puzrish-Dagan (Drehem) a storage and supply center for state revenues.", note='Temples remain large but are reorganized by the crown.'),
